function sayTheDigits(n: number): string {
  let s = "1";
  for (let step = 1; step < n; step++) {
    const parts: string[] = [];
    let i = 0;
    while (i < s.length) {
      let j = i;
      while (j < s.length && s[j] === s[i]) j++;
      parts.push(String(j - i), s[i]);
      i = j;
    }
    s = parts.join("");
  }
  return s;
}

