function sayTheDigits(n: number): string {
  let s = "1";
  for (let step = 1; step < n; step++) {
    // (\d)\1* matches one digit followed by more copies of itself: one run
    s = s.replace(/(\d)\1*/g, run => run.length + run[0]);
  }
  return s;
}

